    constructor(C _c) {
        c = _c;
    }

    function run(address _log) public payable {
        // Precondition: the contract must not be initialized before the first setting.
        (bool initBefore) = false;
        if (address(c) != address(0)) {
            // Observe initialization indirectly via the setter's behavior below.
        }

        // First call, before any Initialized(): must succeed and store the address.
        bool firstReverted;
        try c.SetLogFile(_log) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        address storedAfterFirst = address(c.Log());

        // Now mark the contract as initialized.
        c.Initialized();

        address storedBeforeSecond = address(c.Log());

        // Second call, after Initialized(): must revert and leave Log unchanged.
        bool secondReverted;
        try c.SetLogFile(address(this)) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        address storedAfterSecond = address(c.Log());

        assert(
            !firstReverted &&
            storedAfterFirst == _log &&
            secondReverted &&
            storedAfterSecond == storedBeforeSecond
        );
    }

    receive() external payable {}
}

