contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        // Observe the public state variable before initialization.
        bool before = c.intitalized();

        // The first call to Initialized must succeed on a fresh contract.
        bool reverted1;
        try c.Initialized() { reverted1 = false; } catch { reverted1 = true; }

        // Read the public flag after the first call.
        bool after1 = c.intitalized();

        // A second call to Initialized must also complete (no revert guard on re-initialization).
        bool reverted2;
        try c.Initialized() { reverted2 = false; } catch { reverted2 = true; }

        // Read the public flag after the second call.
        bool after2 = c.intitalized();

        // General rule: Initialized() never reverts, and the public flag becomes true after the
        // first call and stays true (cannot be reset to false by subsequent calls).
        assert(
            !reverted1 &&
            !reverted2 &&
            after1 == true &&
            after2 == true &&
            (before == after1 || before == true)
        );
    }
}

