        // Second call should also succeed (no revert guard on Initialized).
        bool reverted2;
        try c.Initialized() { reverted2 = false; } catch { reverted2 = true; }

        // After initialization, SetMinSum and SetLogFile should revert.
        bool setMinSumReverted;
        try c.SetMinSum(_val) { setMinSumReverted = false; } catch { setMinSumReverted = true; }

        bool setLogFileReverted;
        try c.SetLogFile(_log) { setLogFileReverted = false; } catch { setLogFileReverted = true; }

        // General rule: Initialized() never reverts; once called, other initialization setters revert.
        assert(!reverted1 && !reverted2 && setMinSumReverted && setLogFileReverted);
    }
}

