contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putAmount, uint collectAmount, uint minSum) public payable {
        require(address(this).balance >= putAmount);
        require(minSum >= 0);

        c.SetMinSum(minSum);
        c.Put{value: putAmount}(lockTime);

        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));

        if (!reverted) {
            assert(
                (balanceBefore >= minSum && balanceBefore >= collectAmount && block.timestamp > unlockTimeBefore)
                && balanceAfter == balanceBefore - collectAmount
                && unlockTimeAfter == unlockTimeBefore
            );
        } else {
            assert(
                !(balanceBefore >= minSum && balanceBefore >= collectAmount && block.timestamp > unlockTimeBefore)
                && balanceAfter == balanceBefore
                && unlockTimeAfter == unlockTimeBefore
            );
        }
    }

    receive() external payable {}
}

