contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _am, uint _lockTime) public payable {
        // fresh c has MinSum == 0, so balance >= MinSum holds for any deposit >= 0
        require(address(this).balance >= _am, "insufficient balance");

        // Put exactly _am with the caller-supplied lock time; this makes balance == _am
        // and stores unlockTime = block.timestamp + _lockTime (or 0 if _lockTime == 0).
        c.Put{value: _am}(_lockTime);

        (uint unlockTime, uint balanceBefore) = c.Acc(address(this));
        uint minSum = c.MinSum();

        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }

        (, uint balanceAfter) = c.Acc(address(this));

        // For a fresh c with only this Put, the pre-conditions that allow a successful
        // Collect are: stored balance >= MinSum (true when MinSum is 0), stored balance
        // >= _am (exactly equal here), and block.timestamp > unlockTime (only when
        // _lockTime == 0).  If those do not all hold, the stored balance must not shrink
        // (and typically the call does not revert).
        bool conditionsHold = balanceBefore >= minSum && balanceBefore >= _am && block.timestamp > unlockTime;
        assert(conditionsHold || reverted || balanceAfter == balanceBefore);
    }

    receive() external payable {}
}

